wrangle_opportunity.example_vex:
// 5 calyx lobes fading base->top + slight asymmetry; writes P (class=Points)
float theta = atan2(@P.z, @P.x);
float rad = length(set(@P.x, 0.0, @P.z));
float safe = max(rad, 0.0001);
float h = fit(@P.y, 0.0, 1.55, 0.0, 1.0);
float lobe = cos(theta * 5.0) * 0.5 + 0.5;
float botmask = 1.0 - smooth(0.0, 0.4, h);
float push = lobe * botmask * 0.13;
@P.x += (@P.x / safe) * push;
@P.z += (@P.z / safe) * push;
@P.x += @P.y * 0.02;
@P.x += sin(@P.y * 2.0) * 0.02;
